insert into passages (id, text, difficulty_level, b, active) values
('bd5e4301-5039-4e8b-8bda-75380e565120', 'Lily has a small vegetable garden behind her house. Every spring, she plants tomatoes, carrots, and peppers. She waters the plants every morning before school. Her little brother Sam helps her pull out the weeds on weekends. By summer, the garden is full of colorful vegetables. Lily loves picking fresh tomatoes and eating them right away. Her family enjoys salads made from the vegetables all summer long. Last year, Lily won a prize at the town fair for growing the biggest pumpkin.', 1, -2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('e6ac5dc0-77a9-4e15-ad68-3956d8bbb757', 'sentence_completion', 'The room was very ___ because someone had opened all the windows.', NULL, '[{"id": "d", "text": "cold"}, {"id": "a", "text": "dark"}, {"id": "b", "text": "hot"}, {"id": "c", "text": "dirty"}]'::jsonb, 0, '{"strategy": "opened all the windows = פתח את כל החלונות. מה קורה לחדר?", "correct_reason": "cold = קר. חלונות פתוחים מכניסים קור.", "options_analysis": ["נכון! cold = קר — חלונות פתוחים מכניסים אוויר קר", "dark = חשוך — לא קשור לחלונות", "hot = חם — הפוך, חלונות פתוחים לא מחממים", "dirty = מלוכלך — לא קשור לחלונות פתוחים"]}', 1.27, -2.0, 0.25, 1, 'ai', NULL, true),
('3d1a4eed-93d9-40ec-90ea-d1b9ed790fde', 'sentence_completion', 'The children were ___ because they had not slept enough the night before.', NULL, '[{"id": "b", "text": "proud"}, {"id": "a", "text": "cranky"}, {"id": "d", "text": "calm"}, {"id": "c", "text": "excited"}]'::jsonb, 1, '{"strategy": "not slept enough = לא ישנו מספיק. איך מרגישים ילדים עייפים?", "correct_reason": "cranky = רגזניים. חוסר שינה גורם לרוגזנות.", "options_analysis": ["proud = גאים — לא קשור לשינה", "נכון! cranky = רגזניים — תוצאה טבעית של חוסר שינה", "calm = רגועים — הפוך מרגזנות", "excited = נרגשים — לא קשור לחוסר שינה"]}', 1.42, -2.0, 0.25, 1, 'ai', NULL, true),
('c287d82e-dc8c-4177-af83-6d896b10e860', 'sentence_completion', 'She wore a ___ coat because the weather was very cold.', NULL, '[{"id": "d", "text": "short"}, {"id": "b", "text": "light"}, {"id": "a", "text": "thick"}, {"id": "c", "text": "thin"}]'::jsonb, 2, '{"strategy": "weather was very cold = מזג אוויר קר מאוד. איזה מעיל מתאים לקור?", "correct_reason": "thick = עבה. מעיל עבה מתאים לקור.", "options_analysis": ["short = קצר — אורך לא קשור לחום", "light = קל — פחות מתאים לקור עז", "נכון! thick = עבה — מתאים לקור עז", "thin = דק — הפוך ממה שמתאים לקור"]}', 1.33, -2.0, 0.25, 1, 'ai', NULL, true),
('4f1423fc-3026-4ce3-8d94-6365460ff935', 'sentence_completion', 'The dog was ___ after running around the park for an hour.', NULL, '[{"id": "c", "text": "hungry"}, {"id": "d", "text": "angry"}, {"id": "a", "text": "clean"}, {"id": "b", "text": "tired"}]'::jsonb, 3, '{"strategy": "running around for an hour = רץ במשך שעה. איך מרגיש כלב אחרי ריצה ארוכה?", "correct_reason": "tired = עייף. ריצה ארוכה מעייפת.", "options_analysis": ["hungry = רעב — אפשרי אך פחות ישיר מ''tired''", "angry = כועס — לא קשור לריצה", "clean = נקי — הפוך, ריצה בפארק מלכלכת", "נכון! tired = עייף — תוצאה ישירה של ריצה ארוכה"]}', 1.34, -2.0, 0.25, 1, 'ai', NULL, true),
('a6444ea9-3583-48bf-8f28-61bcc506f114', 'sentence_completion', 'The soup smelled ___ so she decided not to eat it.', NULL, '[{"id": "b", "text": "bad"}, {"id": "a", "text": "warm"}, {"id": "c", "text": "delicious"}, {"id": "d", "text": "sweet"}]'::jsonb, 0, '{"strategy": "decided not to eat it = החליטה לא לאכול. למה מריחים סירבו לאכול?", "correct_reason": "bad = רע. ריח רע גורם לסירוב לאכול.", "options_analysis": ["נכון! bad = רע — ריח רע מסביר סירוב לאכול", "warm = חם — לא סיבה לסרב לאכול", "delicious = טעים — הפוך, לא היו מסרבים לאכול משהו טעים", "sweet = מתוק — לא סיבה לסרב לאכול"]}', 1.49, -2.0, 0.25, 1, 'ai', NULL, true),
('97113745-efab-49ed-bcbb-10aa27364769', 'sentence_completion', 'The teacher spoke ___ so that all the students could hear her.', NULL, '[{"id": "c", "text": "softly"}, {"id": "a", "text": "loudly"}, {"id": "d", "text": "quietly"}, {"id": "b", "text": "slowly"}]'::jsonb, 1, '{"strategy": "so that all could hear = כדי שכולם ישמעו. איך צריכה מורה לדבר?", "correct_reason": "loudly = בקול רם. קול רם מבטיח שכולם ישמעו.", "options_analysis": ["softly = ברכות — דומה ל''quietly'', הפוך", "נכון! loudly = בקול רם — מבטיח שמיעה לכולם", "quietly = בשקט — הפוך ממטרת השמעה לכולם", "slowly = לאט — לא קשור לעוצמת הקול"]}', 1.2, -2.0, 0.25, 1, 'ai', NULL, true),
('32772666-4554-4868-887b-94e0f1ffe29c', 'sentence_completion', 'The boy was ___ when his team won the championship game.', NULL, '[{"id": "d", "text": "bored"}, {"id": "a", "text": "sad"}, {"id": "c", "text": "thrilled"}, {"id": "b", "text": "tired"}]'::jsonb, 2, '{"strategy": "won the championship = ניצח באליפות. איך מרגישים אחרי ניצחון?", "correct_reason": "thrilled = נרגש מאוד. ניצחון גורם להתרגשות.", "options_analysis": ["bored = משועמם — הפוך מהתרגשות", "sad = עצוב — הפוך מתגובה לניצחון", "נכון! thrilled = נרגש מאוד — תגובה טבעית לניצחון", "tired = עייף — לא קשור לרגש הניצחון"]}', 1.36, -2.0, 0.25, 1, 'ai', NULL, true),
('ed3d9754-91f0-4e97-9e58-97ef59e0bbf3', 'sentence_completion', 'The bread was too ___ to cut with a regular knife.', NULL, '[{"id": "b", "text": "warm"}, {"id": "a", "text": "soft"}, {"id": "d", "text": "fresh"}, {"id": "c", "text": "hard"}]'::jsonb, 3, '{"strategy": "too ___ to cut = מדי בשביל לחתוך. מה מקשה על חיתוך לחם?", "correct_reason": "hard = קשה. לחם קשה מדי לחתוך רגיל.", "options_analysis": ["warm = חם — לא קשור לקושי החיתוך", "soft = רך — הפוך, רך קל לחיתוך", "fresh = טרי — לחם טרי בד''כ קל לחיתוך", "נכון! hard = קשה — מקשה על חיתוך רגיל"]}', 1.5, -2.0, 0.25, 1, 'ai', NULL, true),
('f4c7e128-e130-4336-b395-1a4a8442ac72', 'sentence_completion', 'The girl was ___ to speak in front of the whole class.', NULL, '[{"id": "a", "text": "shy"}, {"id": "c", "text": "excited"}, {"id": "d", "text": "angry"}, {"id": "b", "text": "hungry"}]'::jsonb, 0, '{"strategy": "speak in front of the whole class = לדבר מול כל הכיתה. איך מרגישים ילדים רבים לגבי זה?", "correct_reason": "shy = ביישנית. דיבור מול קהל גדול גורם לביישנות.", "options_analysis": ["נכון! shy = ביישנית — תגובה נפוצה לדיבור מול קהל", "excited = נרגשת — אפשרי אך פחות נפוץ מביישנות", "angry = כועסת — לא קשור לדיבור מול כיתה", "hungry = רעבה — לא קשור בכלל"]}', 1.39, -2.0, 0.25, 1, 'ai', NULL, true),
('85539bd1-38ba-4f7c-b8b3-5661cb5206fa', 'sentence_completion', 'The water in the pool was ___ so nobody wanted to swim.', NULL, '[{"id": "c", "text": "warm"}, {"id": "a", "text": "freezing"}, {"id": "d", "text": "clear"}, {"id": "b", "text": "clean"}]'::jsonb, 1, '{"strategy": "nobody wanted to swim = אף אחד לא רצה לשחות. מה מרתיע משחייה?", "correct_reason": "freezing = קפואה. מים קפואים מרתיעים משחייה.", "options_analysis": ["warm = חמימים — נעים לשחייה, לא סיבה לסירוב", "נכון! freezing = קפואה — מסביר למה לא רצו לשחות", "clear = צלולים — לא סיבה לסרב לשחות", "clean = נקיים — לא סיבה לסרב לשחות"]}', 1.34, -2.0, 0.25, 1, 'ai', NULL, true),
('fa6c5017-1bb8-4575-807b-3e0dbba47273', 'sentence_completion', 'The old bicycle was too ___ to ride safely.', NULL, '[{"id": "c", "text": "clean"}, {"id": "d", "text": "new"}, {"id": "a", "text": "broken"}, {"id": "b", "text": "fast"}]'::jsonb, 2, '{"strategy": "too ___ to ride safely = מדי בשביל לרכוב בבטחה. מה מסוכן באופניים ישנים?", "correct_reason": "broken = שבורים. אופניים שבורים לא בטוחים לרכיבה.", "options_analysis": ["clean = נקיים — לא קשור לבטיחות", "new = חדשים — הפוך, אופניים ישנים לא חדשים", "נכון! broken = שבורים — מסביר סכנה ברכיבה", "fast = מהירים — לא קשור לבטיחות רכיבה"]}', 1.48, -2.0, 0.25, 1, 'ai', NULL, true),
('00f91c2b-8f3a-46a6-9ccd-742e165209a3', 'sentence_completion', 'The little girl was ___ of the big dog next door.', NULL, '[{"id": "d", "text": "tired"}, {"id": "c", "text": "bored"}, {"id": "a", "text": "proud"}, {"id": "b", "text": "afraid"}]'::jsonb, 3, '{"strategy": "big dog next door = כלב גדול מהשכנים. איך מרגישה ילדה קטנה כלפי כלב גדול?", "correct_reason": "afraid = מפוחדת. כלב גדול מפחיד ילדה קטנה.", "options_analysis": ["tired = עייפה — לא קשור לכלב", "bored = משועממת — לא קשור לכלב", "proud = גאה — לא קשור לכלב שכנים", "נכון! afraid = מפוחדת — תגובה טבעית לכלב גדול"]}', 1.29, -2.0, 0.25, 1, 'ai', NULL, true),
('d4a75a4e-ea64-4335-8f35-d27870e3a285', 'restatement', 'The bus arrived late, so the students missed the first class.', NULL, '[{"id": "d", "text": "The students missed the first class because the bus arrived late."}, {"id": "c", "text": "The bus arrived early, so the students were on time."}, {"id": "b", "text": "The bus arrived late after the first class ended."}, {"id": "a", "text": "The students missed the bus because class started late."}]'::jsonb, 0, '{"strategy": "arrived late, so missed = הגיע מאוחר, לכן פספסו. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "הפוך — ''early'' סותר ''late''", "הופך את סדר האירועים", "הופך סיבה ותוצאה"]}', 1.38, -2.0, 0.25, 1, 'ai', NULL, true),
('55831a9b-32d4-4b74-aed1-2105e61240b7', 'restatement', 'She wrote a letter to her grandmother every week.', NULL, '[{"id": "b", "text": "Her grandmother wrote a letter to her every week."}, {"id": "c", "text": "Every week, she wrote a letter to her grandmother."}, {"id": "d", "text": "She wrote a letter to her grandmother once a year."}, {"id": "a", "text": "She never wrote letters to her grandmother."}]'::jsonb, 1, '{"strategy": "every week = כל שבוע. הרגל קבוע.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["הפוך תפקידים — היא כתבה לסבתא, לא להפך", "נכון! אותה עובדה בדיוק", "''פעם בשנה'' סותר ''every week''", "סותר ''every week''"]}', 1.25, -2.0, 0.25, 1, 'ai', NULL, true),
('8ad1709f-ae92-421f-9d97-e2ccf73fbc57', 'restatement', 'The kitten hid under the bed because it was scared of the thunder.', NULL, '[{"id": "d", "text": "The thunder started after the kitten hid under the bed."}, {"id": "c", "text": "The kitten hid under the bed because it liked the thunder."}, {"id": "a", "text": "Because it was scared of the thunder, the kitten hid under the bed."}, {"id": "b", "text": "The kitten was not scared of the thunder at all."}]'::jsonb, 2, '{"strategy": "hid because scared = התחבא כי פחד. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הופך את סדר האירועים", "סותר ''scared of the thunder''", "נכון! אותה סיבה-תוצאה בדיוק", "סותר לגמרי — החתלתול כן פחד"]}', 1.36, -2.0, 0.25, 1, 'ai', NULL, true),
('30cc2ebb-9a35-4115-a493-2ed3e145908f', 'restatement', 'He practices the piano for one hour every day.', NULL, '[{"id": "c", "text": "He practices the piano once a week."}, {"id": "b", "text": "He never practices the piano."}, {"id": "d", "text": "He practices the piano for two hours every day."}, {"id": "a", "text": "Every day, he practices the piano for one hour."}]'::jsonb, 3, '{"strategy": "for one hour every day = שעה כל יום. הרגל קבוע.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["''פעם בשבוע'' סותר ''every day''", "סותר ''every day''", "''שעתיים'' סותר ''one hour'' — משך זמן שונה מהמקור", "נכון! אותה עובדה בדיוק בסדר מילים הפוך"]}', 1.41, -2.0, 0.25, 1, 'ai', NULL, true),
('9686fb8d-6df1-4a6f-ae32-f227030ea238', 'restatement', 'The museum was closed on Mondays, so they visited on Tuesday instead.', NULL, '[{"id": "c", "text": "They visited on Tuesday because the museum was closed on Mondays."}, {"id": "b", "text": "The museum was open every day of the week."}, {"id": "a", "text": "They visited on Monday because the museum was open."}, {"id": "d", "text": "The museum closed on Tuesday because they visited."}]'::jsonb, 0, '{"strategy": "closed...so visited instead = סגור...לכן ביקרו בתחלופה. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "סותר ''closed on Mondays''", "סותר לגמרי — ביקרו ביום שלישי, לא שני", "הופך סיבה ותוצאה"]}', 1.46, -2.0, 0.25, 1, 'ai', NULL, true),
('e5c4bed3-a6dd-439b-9630-cddba17c9b79', 'restatement', 'The farmer planted vegetables in the spring.', NULL, '[{"id": "a", "text": "The farmer never planted any vegetables."}, {"id": "d", "text": "In the spring, the farmer planted vegetables."}, {"id": "b", "text": "The farmer harvested vegetables in the spring."}, {"id": "c", "text": "The farmer planted vegetables in the winter."}]'::jsonb, 1, '{"strategy": "planted in the spring = שתל באביב. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["סותר לגמרי — הוא כן שתל", "נכון! אותה עובדה בדיוק", "''קצר'' — פועל שונה, לא ניסוח מחדש נכון", "''חורף'' סותר ''spring''"]}', 1.27, -2.0, 0.25, 1, 'ai', NULL, true),
('db02149c-0e0b-4a52-a3b5-68e03cd97e15', 'restatement', 'The girl was proud of her painting, so she hung it on her wall.', NULL, '[{"id": "a", "text": "She was ashamed of her painting."}, {"id": "c", "text": "She hung the painting before she finished it."}, {"id": "d", "text": "She hung the painting because she was proud of it."}, {"id": "b", "text": "She threw away her painting because she disliked it."}]'::jsonb, 2, '{"strategy": "proud, so hung = גאה, לכן תלתה. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הפוך — ''ashamed'' סותר ''proud''", "הופך את סדר האירועים", "נכון! אותה סיבה-תוצאה בדיוק", "סותר ''hung it on her wall''"]}', 1.24, -2.0, 0.25, 1, 'ai', NULL, true),
('aa8e3710-9936-41ed-8432-b8549be89575', 'restatement', 'The store was crowded, so it took a long time to check out.', NULL, '[{"id": "a", "text": "The store was crowded, but checking out was fast."}, {"id": "d", "text": "It took a long time to check out, so the store became crowded."}, {"id": "b", "text": "The store was empty, so checking out was quick."}, {"id": "c", "text": "It took a long time to check out because the store was crowded."}]'::jsonb, 3, '{"strategy": "crowded, so took long = צפוף, לכן לקח זמן. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר ''took a long time''", "הופך סיבה ותוצאה", "הפוך — ''empty'' סותר ''crowded''", "נכון! אותה סיבה-תוצאה בדיוק"]}', 1.47, -2.0, 0.25, 1, 'ai', NULL, true),
('9961ac49-30b9-489d-b40e-3002f6de7a2c', 'restatement', 'The boy shared his lunch with his friend who forgot his own.', NULL, '[{"id": "d", "text": "The boy shared his lunch because his friend forgot his own."}, {"id": "b", "text": "The boy refused to share his lunch."}, {"id": "c", "text": "His friend shared lunch with the boy."}, {"id": "a", "text": "The boy forgot his own lunch."}]'::jsonb, 0, '{"strategy": "shared...forgot = שיתף...שכח. סיבה-תוצאה מרומזת.", "correct_reason": "אותה סיבה-תוצאה בדיוק בניסוח מפורש.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "סותר ''shared his lunch''", "הפוך תפקידים — הילד שיתף, לא החבר", "הפוך — החבר שכח, לא הילד"]}', 1.24, -2.0, 0.25, 1, 'ai', NULL, true),
('1dfbb045-ea83-4b5e-b82c-acb3a400f9ed', 'restatement', 'The children laughed loudly at the funny clown.', NULL, '[{"id": "c", "text": "The clown laughed loudly at the children."}, {"id": "d", "text": "The children laughed loudly at the funny clown."}, {"id": "b", "text": "The children cried at the funny clown."}, {"id": "a", "text": "The children were silent during the clown''s show."}]'::jsonb, 1, '{"strategy": "משפט פשוט — חזרה מדויקת.", "correct_reason": "זהו הניסוח היחיד הזהה למקור מילה במילה כרעיון.", "options_analysis": ["הפוך תפקידים — הילדים צחקו, לא הליצן", "נכון! אותה עובדה בדיוק", "הפוך — ''cried'' סותר ''laughed''", "סותר ''laughed loudly''"]}', 1.48, -2.0, 0.25, 1, 'ai', NULL, true),
('c94a15b7-2702-49e6-b9a1-e243069ddc0a', 'restatement', 'The old man walked slowly because his legs hurt.', NULL, '[{"id": "d", "text": "His legs hurt because he walked slowly."}, {"id": "c", "text": "The old man''s legs did not hurt at all."}, {"id": "b", "text": "Because his legs hurt, the old man walked slowly."}, {"id": "a", "text": "The old man ran quickly despite his hurting legs."}]'::jsonb, 2, '{"strategy": "walked slowly because hurt = הלך לאט כי כאב. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הופך סיבה ותוצאה", "סותר ''his legs hurt''", "נכון! אותה סיבה-תוצאה בדיוק", "סותר ''walked slowly''"]}', 1.49, -2.0, 0.25, 1, 'ai', NULL, true),
('67b58f32-6bb7-4fc0-b516-c42ed0fdc254', 'restatement', 'The bird flew away as soon as the cat appeared.', NULL, '[{"id": "d", "text": "The cat appeared after the bird flew away."}, {"id": "c", "text": "The bird flew away long before the cat appeared."}, {"id": "a", "text": "The bird stayed even after the cat appeared."}, {"id": "b", "text": "As soon as the cat appeared, the bird flew away."}]'::jsonb, 3, '{"strategy": "as soon as = מיד כאשר. סמיכות זמנים.", "correct_reason": "אותה סמיכות זמנים בדיוק, סדר מילים הפוך.", "options_analysis": ["הופך את סדר האירועים", "הופך את סדר הזמנים", "סותר ''flew away'' — הציפור כן עפה", "נכון! אותה סמיכות זמנים בדיוק"]}', 1.46, -2.0, 0.25, 1, 'ai', NULL, true),
('4776eee8-8d5c-43f6-811e-2b8b6469785c', 'reading_comprehension', 'What is the passage mainly about?', 'bd5e4301-5039-4e8b-8bda-75380e565120', '[{"id": "a", "text": "Lily''s vegetable garden and how she cares for it"}, {"id": "d", "text": "A recipe for tomato salad"}, {"id": "b", "text": "A town fair competition"}, {"id": "c", "text": "Sam''s weekend activities"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה מתארת את גינת הירקות של לילי וטיפולה בה.", "correct_reason": "כל הפסקה עוסקת בגינה, בטיפוח שלה ובהנאה שהמשפחה מפיקה ממנה.", "options_analysis": ["נכון! הגינה והטיפול בה = הנושא הכולל", "לא מוזכרת מתכון בפסקה", "פרט משני שמוזכר בסוף, לא הנושא המרכזי", "פרט משני, לא הנושא המרכזי"]}', 1.28, -2.0, 0.25, 1, 'ai', NULL, true),
('fce9646a-bb5f-4597-aa3d-c54f524ab868', 'reading_comprehension', 'What does Lily plant every spring?', 'bd5e4301-5039-4e8b-8bda-75380e565120', '[{"id": "d", "text": "Only tomatoes"}, {"id": "b", "text": "Tomatoes, carrots, and peppers"}, {"id": "c", "text": "Flowers and herbs"}, {"id": "a", "text": "Only pumpkins"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את רשימת הצמחים בפסקה.", "correct_reason": "הפסקה אומרת: ''she plants tomatoes, carrots, and peppers''.", "options_analysis": ["חלקי בלבד", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר שנשתלים כל אביב, רק זכתה בפרס עליו"]}', 1.33, -2.0, 0.25, 1, 'ai', NULL, true),
('1702652f-7aed-4e1e-b87e-7922ba596d99', 'reading_comprehension', 'Who helps Lily pull out the weeds?', 'bd5e4301-5039-4e8b-8bda-75380e565120', '[{"id": "a", "text": "Her mother"}, {"id": "c", "text": "Her teacher"}, {"id": "d", "text": "Her brother Sam"}, {"id": "b", "text": "No one helps her"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש מי עוזר בגינה.", "correct_reason": "הפסקה אומרת: ''Her little brother Sam helps her pull out the weeds on weekends''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "סותר את הפסקה — סאם כן עוזר"]}', 1.3, -2.0, 0.25, 1, 'ai', NULL, true),
('a6190b29-981d-4605-9cb1-7ecdcf934baf', 'reading_comprehension', 'What does Lily like to do with fresh tomatoes?', 'bd5e4301-5039-4e8b-8bda-75380e565120', '[{"id": "a", "text": "Give them all away"}, {"id": "c", "text": "Store them for winter"}, {"id": "d", "text": "Sell them at the market"}, {"id": "b", "text": "Pick and eat them right away"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש מה לילי אוהבת לעשות עם עגבניות.", "correct_reason": "הפסקה אומרת: ''Lily loves picking fresh tomatoes and eating them right away''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.28, -2.0, 0.25, 1, 'ai', NULL, true),
('0730cba3-6b2c-4d90-8f23-a5db376a1097', 'reading_comprehension', 'What did Lily win at the town fair last year?', 'bd5e4301-5039-4e8b-8bda-75380e565120', '[{"id": "d", "text": "A prize for the biggest pumpkin"}, {"id": "a", "text": "She did not win anything"}, {"id": "c", "text": "A prize for the tallest tomato plant"}, {"id": "b", "text": "A prize for the best salad"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את ההישג בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''Last year, Lily won a prize at the town fair for growing the biggest pumpkin''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "סותר את הפסקה — היא כן זכתה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.15, -2.0, 0.25, 1, 'ai', NULL, true);